out={"timestamp":datetime.now(timezone.utc).isoformat(),"root":str(W),"files":{}}
for n,e in expected.items():
 p=W/n;b=p.read_bytes();assert len(b)<=2000000,(n,len(b));h=hashlib.sha256(b).hexdigest();assert h==e["sha256"],(n,h,e)
 out["files"][n]={"bytes":len(b),"sha256":h,"base64":base64.b64encode(b).decode()}
assert sum(e["bytes"] for e in out["files"].values())<80000000
blob=gzip.compress(json.dumps(out,sort_keys=True).encode(),mtime=0)
subprocess.run(["tmux","load-buffer","-b","ia840f_mempim_capture01","-"],input=blob,check=True)
subprocess.run(["tmux","set-buffer","-b","ia840f_mempim_capture01_sha256",hashlib.sha256(blob).hexdigest()],check=True)
print("CAPTURED",len(out["files"]),"SHA256",hashlib.sha256(blob).hexdigest(),flush=True)
